using Gtk 4.0;

template $MathVariablePopover: $MathPopover {
  styles [
    "math-popover",
  ]

  Stack stack {
    transition-type: slide_left_right;
    interpolate-size: true;
    vhomogeneous: false;

    Box content {
      orientation: vertical;

      ScrolledWindow variable_list_scrolled {
        propagate-natural-height: true;
        max-content-height: 290;
        width-request: 250;
        hscrollbar-policy: never;

        styles [
          "undershoot-bottom",
        ]

        Box {
          orientation: vertical;

          ListBox variable_list {
            selection-mode: none;
            row-activated => $insert_variable_cb();
          }

          Separator {}

          Label {
            label: _("Constants");
            xalign: 0;

            styles [
              "dimmed",
            ]
          }

          ListBox constant_list {
            selection-mode: none;
            row-activated => $open_submenu_cb();

            styles [
              "category-list",
            ]
          }
        }
      }

      Box add_variable_box {
        Entry name_entry {
          placeholder-text: _("Variable name");
          receives-default: true;
          hexpand: true;
          input-hints: no_emoji;
          accessibility {
            error-message: error_label;
          }
          activate => $store_variable_cb();
        }

        Button add_button {
          sensitive: false;
          tooltip-text: _("Store value into existing or new variable");
          icon-name: "document-save-symbolic";
          clicked => $store_variable_cb();
        }
      }

      Revealer {
        Label error_label {
          xalign: 0;
          wrap: true;
          wrap-mode: word_char;
          max-width-chars: 0;
        }
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

menu window_menu {
  section {
    item {
      label: _("_Basic");
      action: "win.mode";
      target: "basic";
    }

    item {
      label: _("_Advanced");
      action: "win.mode";
      target: "advanced";
    }

    item {
      label: _("_Financial");
      action: "win.mode";
      target: "financial";
    }

    item {
      label: _("_Programming");
      action: "win.mode";
      target: "programming";
    }

    item {
      label: _("_Keyboard");
      action: "win.mode";
      target: "keyboard";
    }

    item {
      label: _("_Conversion");
      action: "win.mode";
      target: "conversion";
    }
  }
}

menu primary_menu {
  section {
    item {
      label: _("_New Window");
      action: "app.new-window";
    }
  }

  section {
    item {
      label: _("_Clear History");
      action: "win.clear";
      hidden-when: "action-disabled";
    }
  }

  section {
    label: _("Result Format");

    item {
      /* Translators: entry of the Setup submenu of the hamburger menu (with a mnemonic that appears when pressing Alt); set result format to "automatic"; other possible options are "_Fixed", "_Scientific" and "_Engineering" */
      label: _("_Automatic");
      action: "win.number-format";
      target: "automatic";
    }

    item {
      /* Translators: entry of the Setup submenu of the hamburger menu (with a mnemonic that appears when pressing Alt); set result format to "fixed"; other possible options are "_Automatic", "_Scientific" and "_Engineering" */
      label: _("_Fixed");
      action: "win.number-format";
      target: "fixed";
    }

    item {
      /* Translators: entry of the Setup submenu of the hamburger menu (with a mnemonic that appears when pressing Alt); set result format to "scientific"; other possible options are "_Fixed", "_Automatic" and "_Engineering" */
      label: _("_Scientific");
      action: "win.number-format";
      target: "scientific";
    }

    item {
      /* Translators: entry of the Setup submenu of the hamburger menu (with a mnemonic that appears when pressing Alt); set result format to "engineering"; other possible options are "_Fixed", "_Scientific" and "_Automatic" */
      label: _("_Engineering");
      action: "win.number-format";
      target: "engineering";
    }
  }

  section {
    id: "help-section";

    item {
      label: _("_Preferences");
      action: "win.preferences";
    }

    item {
      label: _("_Keyboard Shortcuts");
      action: "app.shortcuts";
    }

    item {
      label: _("_Help");
      action: "app.help";
    }

    item {
      label: _("A_bout Calculator");
      action: "app.about";
    }
  }
}

template $MathWindow: Adw.ApplicationWindow {
  title: _("Calculator");
  height-request: 616;

  Adw.ToolbarView {
    top-bar-style: raised;

    [top]
    Adw.HeaderBar headerbar {
      [title]
      MenuButton menu_button {
        menu-model: window_menu;
        focus-on-click: false;
        always-show-arrow: true;
        can-shrink: true;
        tooltip-text: _("Mode Selection");
      }

      Button undo_button {
        icon-name: "edit-undo-symbolic";
        focus-on-click: false;
        action-name: "win.undo";
        tooltip-text: _("Undo");
      }

      Button redo_button {
        icon-name: "edit-redo-symbolic";
        focus-on-click: false;
        action-name: "win.redo";
        tooltip-text: _("Redo");
      }

      Button back_button {
        icon-name: "go-previous-symbolic";
        action-name: "win.back";
        tooltip-text: _("Financial");
      }

      [end]
      MenuButton primary_menu_button {
        icon-name: "open-menu-symbolic";
        receives-default: false;
        menu-model: primary_menu;
        primary: true;
        tooltip-text: _("Main Menu");
      }
    }

    content: Adw.Clamp {
      /* 10*64px button width + 9*4px spacing + 2*12px margin = 700 width.
         Update the panel size in CSS accordingly. */
      maximum-size: 700;
      tightening-threshold: 700;
      unit: px;

      Box {
        vexpand: true;
        orientation: vertical;

        Box display_box {
          overflow: hidden;
          orientation: vertical;

          styles [
            "card",
            "display-container",
          ]

          $HistoryView history {
            overflow: "hidden";
          }

          $MathDisplay _display {
            equation: bind template.equation;
          }
        }

        $MathConverter _converter {
          equation: bind template.equation;

          styles [
            "card",
            "display-container",
          ]
        }

        $MathButtons _buttons {
          equation: bind template.equation;
          converter: "_converter";
        }
      }
    };
  }
}
